function getLevelById(levelId) {
    return ALL_LEVELS.find(l => l.id === levelId);
}

// Функция получения уровней по категории
function getLevelsByCategory(categoryId) {
    return ALL_LEVELS.filter(l => l.categoryId === categoryId);
}

// Функция получения уровней по категории и сложности
function getLevelsByCategoryAndDifficulty(categoryId, difficulty) {
    const result = ALL_LEVELS.filter(l => l.categoryId === categoryId && l.difficulty === difficulty);
    // Сортируем по номеру уровня
    result.sort((a, b) => a.levelNum - b.levelNum);
    return result;
}

// Функция перемешивания массива (алгоритм Фишера-Йетса)
function shuffleArray(array) {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
}

function getNextWordColor() {
    // Если список доступных цветов пуст - перезаполняем
    if (availableColors.length === 0) {
        // Создаем копию всех цветов и перемешиваем
        availableColors = [...WORD_COLORS];
        shuffleArray(availableColors);
        console.log('🔄 Цвета обновлены, доступно:', availableColors.length);
    }    
    // Берем случайный цвет из доступных
    const randomIndex = Math.floor(Math.random() * availableColors.length);
    const color = availableColors[randomIndex];
    
    // Удаляем выбранный цвет из доступных
    availableColors.splice(randomIndex, 1);
    
    return color;
}

